import { Card } from "./Card";
import { Divider } from "./Divider";

const usd = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });

export function PriceBreakdown({
  nightlyRate,
  nights,
  cleaningFee,
  taxRate,
}: {
  nightlyRate: number;
  nights: number;
  cleaningFee: number;
  taxRate: number;
}) {
  const staySubtotal = nightlyRate * nights;
  const taxes = (staySubtotal + cleaningFee) * taxRate;
  const total = staySubtotal + cleaningFee + taxes;

  return (
    <Card title="Price breakdown">
      <dl className="space-y-2">
        <div className="flex justify-between">
          <dt>{usd.format(nightlyRate)} × {nights} {nights === 1 ? "night" : "nights"}</dt>
          <dd>{usd.format(staySubtotal)}</dd>
        </div>
        <div className="flex justify-between">
          <dt>Cleaning fee</dt>
          <dd>{usd.format(cleaningFee)}</dd>
        </div>
        <div className="flex justify-between">
          <dt>Taxes</dt>
          <dd>{usd.format(taxes)}</dd>
        </div>
        <Divider />
        <div className="flex justify-between font-semibold text-slate-900">
          <dt>Total</dt>
          <dd>{usd.format(total)}</dd>
        </div>
      </dl>
    </Card>
  );
}

